  SET is_supported = false, updated_at = NOW()
  FROM learned l, mml_commands cmd, standard_params sp
  WHERE sf.command_id = cmd.id
    AND sf.standard_path_id = sp.id
    AND cmd.command_code = l.command_code
    AND sp.standard_path = l.standard_path
    AND sf.is_supported = true;
